param([string]$ProjectRoot=(Split-Path -Parent $PSScriptRoot))
$ErrorActionPreference='Stop'
if([Threading.Thread]::CurrentThread.ApartmentState-ne[Threading.ApartmentState]::STA){throw 'Run with powershell.exe -STA.'}
$halcon='C:\Program Files\MVTec\HALCON-20.11-Progress';$env:PATH=(Join-Path $halcon 'bin\x64-win64')+';'+$env:PATH
Add-Type -AssemblyName PresentationFramework
Add-Type -AssemblyName System.Runtime.Serialization
function Assert([bool]$condition,[string]$message){if(-not$condition){throw $message}}
$assembly=[Reflection.Assembly]::LoadFrom((Join-Path $ProjectRoot 'bin\x64\Debug\HalconWinFormsDemo.exe'))
$mainType=$assembly.GetType('HalconWinFormsDemo.MainWindow',$true);$serviceType=$assembly.GetType('HalconWinFormsDemo.Services.RecipeService',$true);$loggerType=$assembly.GetType('HalconWinFormsDemo.Services.AppLogger',$true);$kindType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolKind',$true);$metadataType=$assembly.GetType('HalconWinFormsDemo.Models.ToolMetadata',$true);$parametersType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolParameterData',$true)
$private=[Reflection.BindingFlags]'Instance,NonPublic';$all=[Reflection.BindingFlags]'Instance,NonPublic,Public';$static=[Reflection.BindingFlags]'Static,Public,NonPublic';$temp=Join-Path([IO.Path]::GetTempPath())('halcon-vm-s55-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($temp)|Out-Null
$service=$serviceType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$logger=$loggerType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$window=$mainType.GetConstructor($private,$null,[Type[]]@($serviceType,$loggerType),$null).Invoke([object[]]@($service,$logger))
function Field([string]$name){$value=$mainType.GetField($name,$all).GetValue($window);Write-Output -NoEnumerate $value}
function Kind([string]$name){[Enum]::Parse($kindType,$name)}
function Tool([string]$kind,[string]$name){$mainType.GetMethod('CreateFlowTool',$private).Invoke($window,[object[]]@((Kind $kind),$name,$true,$null))}
function Out($tool,[string]$name){$args=[object[]]@($name,$null);Assert($tool.GetType().GetMethod('TryGetOutputValue').Invoke($tool,$args))('Missing output '+$name);$args[1]}
function Run($tool){$mainType.GetMethod('ExecuteFlowTool',$private).Invoke($window,[object[]]@($tool,'S55 smoke'))}
function LoadDock($tool){$raw=$tool.PSObject.BaseObject;$mainType.GetMethod('LoadDockConfigurationDraft',$private).Invoke($window,[object[]]@($raw))|Out-Null}
try{
  $flow=Field 'flowTools';$source=Tool ImageSource 'Text Inputs';$assemblyTool=Tool TextAssembly 'Text Assembly';$parser=Tool TextParser 'Text Parser';$judge=Tool NumericJudge 'Parsed Number Judge';$envelope=Tool TextAssembly 'Parsed Text Consumer';foreach($tool in @($source,$assemblyTool,$parser,$judge,$envelope)){$flow.Add($tool)}
  $unicode=([string][char]0x6279)+([string][char]0x6B21)+'-A7';$source.SetOutputValue('SN',$unicode);$source.SetOutputValue('Width',[double]12.5);$source.SetOutputValue('ResultCode','OK');$source.ResultCode='OK'
  $assemblyTool.SetInputBinding('String',$source.ToolId,'SN');$assemblyTool.SetInputBinding('Number',$source.ToolId,'Width');$assemblyTool.SetInputBinding('ResultCode',$source.ToolId,'ResultCode');$assemblyTool.Parameters.TextAssemblyTemplate='{String}{Separator}{Number}{Separator}{Separator}{ResultCode}';$assemblyTool.Parameters.TextAssemblySeparator='|';$assemblyTool.Parameters.TextAssemblyNumberFormat='0.0';$assemblyTool.Parameters.TextAssemblyEmptyPolicy='Keep';Assert((Run $assemblyTool).ResultCode-eq'OK') 'Assembly source failed'
  $parser.SetInputBinding('String',$assemblyTool.ToolId,'Text');$parser.Parameters.TextParserMode='Literal';$parser.Parameters.TextParserPattern='|';$parser.Parameters.TextParserFieldIndex=2;$parser.Parameters.TextParserTrim=$true;$parser.Parameters.TextParserEmptyPolicy='Keep';$parser.Parameters.TextParserConvertNumber=$true
  $inputs=$metadataType.GetMethod('GetInputPorts',[Reflection.BindingFlags]'Static,Public').Invoke($null,[object[]]@((Kind TextParser)));$outputs=$metadataType.GetMethod('GetOutputPorts',[Reflection.BindingFlags]'Static,Public').Invoke($null,[object[]]@((Kind TextParser)));Assert($inputs.Count-eq1-and$inputs[0].DataType-eq'String') 'Text Parser String input contract failed';Assert(($outputs|Where-Object PortName -eq 'Number').DataType-eq'Number'-and($outputs|Where-Object PortName -eq 'Matched').DataType-eq'Boolean') 'Text Parser output contract failed'
  $record=Run $parser;Assert($record.ResultCode-eq'OK'-and(Out $parser Text)-eq'12.5') 'Literal parsing failed';Assert([Math]::Abs(([double](Out $parser Number))-12.5)-lt0.000001) 'Invariant numeric conversion failed';Assert([int](Out $parser FieldCount)-eq4-and[bool](Out $parser Matched)) 'Literal field count/matched failed'
  $judge.SetInputBinding('Value',$parser.ToolId,'Number');$judge.InputToolId=$parser.ToolId;$judge.InputPortName='Number';$judge.NumericLowerLimit=12;$judge.NumericUpperLimit=13;Assert((Run $judge).ResultCode-eq'OK') 'Parser Number did not drive Numeric Judge'
  $envelope.SetInputBinding('String',$parser.ToolId,'Text');$envelope.Parameters.TextAssemblyTemplate='VALUE={String}';Assert((Run $envelope).ResultCode-eq'OK'-and(Out $envelope Text)-eq'VALUE=12.5') 'Parser Text did not drive downstream Text Assembly'

  $parser.Parameters.TextParserFieldIndex=3;$parser.Parameters.TextParserEmptyPolicy='Keep';$parser.Parameters.TextParserConvertNumber=$false;$keep=Run $parser;Assert($keep.ResultCode-eq'OK'-and(Out $parser Text)-eq'') 'Keep consecutive empty field failed'
  $parser.Parameters.TextParserEmptyPolicy='Skip';$skip=Run $parser;Assert($skip.ResultCode-eq'OK'-and(Out $parser Text)-eq'OK'-and[int](Out $parser FieldCount)-eq3) 'Skip empty field failed'
  $parser.Parameters.TextParserEmptyPolicy='Reject';Assert((Run $parser).ResultCode-eq'NG'-and([string]$parser.ErrorMessage).Length-gt0) 'Reject empty field failed'
  $parser.Parameters.TextParserEmptyPolicy='Keep';$parser.Parameters.TextParserFieldIndex=9;Assert((Run $parser).ResultCode-eq'NG'-and -not[bool](Out $parser Matched)) 'Out-of-range field did not return NG'

  $source.SetOutputValue('SN','VALUE=-3.25;VALUE=8.5');$parser.SetInputBinding('String',$source.ToolId,'SN');$parser.Parameters.TextParserMode='Regex';$parser.Parameters.TextParserPattern='VALUE=([-+]?\d+(?:\.\d+)?)';$parser.Parameters.TextParserFieldIndex=2;$parser.Parameters.TextParserConvertNumber=$true;Assert((Run $parser).ResultCode-eq'OK'-and(Out $parser Text)-eq'8.5'-and[Math]::Abs(([double](Out $parser Number))-8.5)-lt0.000001) 'Regex capture/index failed';Assert([int](Out $parser FieldCount)-eq2) 'Regex match count failed'
  $parser.Parameters.TextParserPattern='MISSING=(\d+)';Assert((Run $parser).ResultCode-eq'NG'-and -not[bool](Out $parser Matched)) 'Regex no-match failed'
  $parser.Parameters.TextParserPattern='(';$invalid=$parser.Parameters.Validate((Kind TextParser));Assert(([string]$invalid).Length-gt0) 'Invalid regex validation failed'
  $parser.Parameters.TextParserMode='Literal';$parser.Parameters.TextParserPattern='\n';$parser.Parameters.TextParserFieldIndex=2;$parser.Parameters.TextParserConvertNumber=$false;$source.SetOutputValue('SN',"A`n"+$unicode);Assert((Run $parser).ResultCode-eq'OK'-and(Out $parser Text)-eq$unicode) 'Escaped newline delimiter failed'
  $parser.Parameters.TextParserPattern='|';$parser.Parameters.TextParserFieldIndex=1;$parser.Parameters.TextParserConvertNumber=$true;$source.SetOutputValue('SN','ABC');Assert((Run $parser).ResultCode-eq'NG'-and[bool](Out $parser Matched)-and$null-eq(Out $parser Number)) 'Invalid numeric conversion failed'

  $serializer=[System.Runtime.Serialization.Json.DataContractJsonSerializer]::new($parametersType);$bytes=[Text.Encoding]::UTF8.GetBytes('{}');$stream=New-Object IO.MemoryStream(,$bytes);try{$old=$serializer.ReadObject($stream)}finally{$stream.Dispose()};$old.Normalize();Assert($old.TextParserMode-eq'Literal'-and$old.TextParserPattern-eq','-and$old.TextParserFieldIndex-eq1-and$old.TextParserTrim) 'Old recipe Text Parser defaults failed'

  LoadDock $parser;Assert((Field 'DockTextParserPanel').Visibility.ToString()-eq'Visible') 'Text Parser dock panel is missing';$summary=[string](Field 'DockKeyParameterSummaryText').Text;$keyMatch=[regex]::Match($summary,'(\d+)');Assert($keyMatch.Success-and[int]$keyMatch.Groups[1].Value-eq4)('Unexpected Text Parser key summary: '+$summary);$advanced=Field 'dockAdvancedParameterRows';Assert($advanced.Count-eq2-and$advanced[0].Row.Height.Value-eq0-and$advanced[1].Row.Height.Value-eq0) 'Text Parser advanced rows are not collapsed'
  $mainType.GetMethod('UpdateRightTaskNavigationState',$private).Invoke($window,[object[]]@('Parameters'))|Out-Null;Assert((Field 'RightConfigurationRow').MinHeight-ge300-and(Field 'ImageWorkspaceRow').MinHeight-eq230) 'Parameter task did not enlarge the lower workspace';$header=(Field 'DockTaskHeaderBorder').Child;Assert($header.RowDefinitions.Count-eq2) 'Dock task header is not compact';Assert((Field 'DockQuickInputText').Visibility.ToString()-eq'Collapsed') 'Repeated input summary is still exposed';Assert((Field 'DockTextParserModeComboBox').Visibility.ToString()-eq'Visible'-and(Field 'DockTextParserFieldIndexTextBox').Visibility.ToString()-eq'Visible') 'Key fields are not directly visible'
  $mainType.GetMethod('UpdateRightTaskNavigationState',$private).Invoke($window,[object[]]@('Io'))|Out-Null;Assert((Field 'RightConfigurationRow').MinHeight-eq210-and(Field 'ImageWorkspaceRow').MinHeight-eq280) 'Non-parameter task layout was not restored';$mainType.GetMethod('UpdateRightTaskNavigationState',$private).Invoke($window,[object[]]@('Parameters'))|Out-Null

  (Field 'DockTextParserPatternTextBox').Text=';';(Field 'DockTextParserFieldIndexTextBox').Text='1';$oldPattern=$parser.Parameters.TextParserPattern;$apply=$mainType.GetMethod('ApplyDockConfigurationDraft',$private);Assert([bool]$apply.Invoke($window,[object[]]@($true))) 'Text Parser dock Apply failed';Assert($parser.Parameters.TextParserPattern-eq';') 'Applied parser pattern was not stored'
  $mainType.GetMethod('UndoFlowEditButton_Click',$private).Invoke($window,[object[]]@($null,$null))|Out-Null;$restored=$flow|Where-Object ToolId -eq $parser.ToolId|Select-Object -First 1;Assert($restored.Parameters.TextParserPattern-eq$oldPattern) 'Text Parser undo failed';$mainType.GetMethod('RedoFlowEditButton_Click',$private).Invoke($window,[object[]]@($null,$null))|Out-Null;$restored=$flow|Where-Object ToolId -eq $parser.ToolId|Select-Object -First 1;Assert($restored.Parameters.TextParserPattern-eq';') 'Text Parser redo failed'
  LoadDock $restored;$list=Field 'FlowToolList';$list.SelectedItems.Clear();$list.SelectedItem=$restored;$before=$flow.Count;$mainType.GetMethod('DuplicateFlowToolButton_Click',$private).Invoke($window,[object[]]@($null,$null))|Out-Null;$copy=$flow|Where-Object{$_.Kind.ToString()-eq'TextParser'-and$_.ToolId-ne$restored.ToolId}|Select-Object -Last 1;Assert($flow.Count-eq($before+1)-and$copy.Parameters.TextParserPattern-eq';') 'Text Parser copy/parameter cloning failed'
  $recipe=$mainType.GetMethod('CaptureRecipe',$private).Invoke($window,@());$saved=$recipe.ToolFlow|Where-Object ToolId -eq $restored.ToolId|Select-Object -First 1;Assert($saved.Parameters.TextParserMode-eq'Literal'-and$saved.Parameters.TextParserPattern-eq';') 'Text Parser recipe persistence failed'
  Write-Output 'S55 compact parameter workspace and Text Parser literal/regex/downstream/recipe lifecycle passed'
}finally{$mainType.GetField('recipeCloseConfirmed',$private).SetValue($window,$true);$window.Close();if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force}}
